export const skeletonDefaults = {"height":12,"radius":6,"duration":1600,"ease":"cubic-bezier(0.22, 1, 0.36, 1)","delay":150,"fadeDuration":300} as const;
export const spinnerDefaults = {"size":14,"duration":800,"trackOpacity":0.18,"strokeWidth":1.8} as const;
export const skeletonCss = ".kalos-skeleton,.kalos-loading{--kalos-skeleton-fill:rgba(0, 0, 0, 0.06);--kalos-skeleton-sheen:rgba(255, 255, 255, 0.7);--kalos-skeleton-radius:6px;--kalos-skeleton-duration:1600ms;--kalos-skeleton-ease:cubic-bezier(0.22, 1, 0.36, 1);--kalos-skeleton-delay:150ms;--kalos-skeleton-fade-duration:300ms}
:where(.dark,[data-theme=dark]) :is(.kalos-skeleton,.kalos-loading){--kalos-skeleton-fill:rgba(255, 255, 255, 0.09);--kalos-skeleton-sheen:rgba(255, 255, 255, 0.06)}
.kalos-skeleton {
  position: relative;
  display: block;
  flex: none;
  box-sizing: border-box;
  max-width: 100%;
  overflow: hidden;
  border-radius: var(--kalos-skeleton-radius);
  background: var(--kalos-skeleton-fill);
}
.kalos-skeleton::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent, var(--kalos-skeleton-sheen), transparent);
  translate: -100% 0;
  animation: kalos-skeleton-sweep var(--kalos-skeleton-duration) var(--kalos-skeleton-ease) infinite;
}
.kalos-skeleton-line {
  display: flex;
  align-items: center;
  min-width: 0;
  max-width: 100%;
}
.kalos-loading {
  animation: kalos-skeleton-enter var(--kalos-skeleton-fade-duration) ease var(--kalos-skeleton-delay) both;
}
@keyframes kalos-skeleton-sweep {
  60%, 100% { translate: 100% 0; }
}
@keyframes kalos-skeleton-enter {
  from { opacity: 0; }
  to { opacity: 1; }
}
";
export const spinnerCss = ".kalos-spinner{--kalos-spinner-duration:800ms}
.kalos-spinner {
  display: inline-block;
  flex: none;
  vertical-align: middle;
  animation: kalos-spinner-turn var(--kalos-spinner-duration) linear infinite;
}
@keyframes kalos-spinner-turn {
  to { rotate: 360deg; }
}
";
